    },
    {
        "zhuang": "Gou siengj cienjciengq.",
        "zh": "我想转账。",
        "source": "textbook"
    },
    {
        "zhuang": "Cienjciengq aeu geijlai nanz cij daengz?",
        "zh": "转账要多久才到？",
        "source": "textbook"
    },
    {
        "zhuang": "Ngoenzneix couh daengz lo.",
        "zh": "今天就到了。",
        "source": "textbook"
    },
    {
        "zhuang": "Cingj cam youq aen cueng lawz geiq bauhgoj?",
        "zh": "请问在哪个窗口寄包裹？",
        "source": "textbook"
