    {
        "zhuang": "Geiq di gijdaenj gijgwn.",
        "zh": "寄一些穿的和吃的。",
        "source": "textbook"
    },
    {
        "zhuang": "Gij doxgaiq lawz dwg doxgaiq veizgin ne?",
        "zh": "哪些东西是违禁品呢？",
        "source": "textbook"
