    {
        "zhuang": "Gij caengz hai gvaq haenx geiq ndaej.",
        "zh": "没有开封过的可以邮寄。",
        "source": "textbook"
    },
    {
        "zhuang": "Cingj mwngz dienz mbaw bauhgojdanh neix.",
        "zh": "请您填这张包裹单。",
        "source": "textbook"
    },
    {
        "zhuang": "Sij ndei lo, hawj mwngz.",
        "zh": "写好了，给您。",
        "source": "textbook"
    },
    {
        "zhuang": "A, diegyouq sij mbouj cingcuj geijlai. Diegyouq cingj sij ciengzsaeq bae, mbouj ndaej sij genjcwngh.",
        "zh": "啊，地址写得不太清楚。地址要写全，不能写简称。",
        "source": "textbook"
    },
    {
        "zhuang": "Yienghneix gou lingh sij ba.",
        "zh": "那我重写吧。",
        "source": "textbook"
    },
    {
        "zhuang": "Menhmenh sij, mbouj yungh gip.",
        "zh": "请慢慢写，不用急。",
        "source": "textbook"
    },
    {
        "zhuang": "Baez neix ndaej mboujcaengz?",
        "zh": "这回可以了吧？",
        "source": "textbook"
    },
    {
        "zhuang": "Ndaej lo. Neix dwg mbawfei mwngz.",
        "zh": "可以了。这是您的收据。",
        "source": "textbook"
    },
    {
        "zhuang": "Youq gizlawz lingx bauhgoj?",
        "zh": "在哪里领包裹？",
        "source": "textbook"
    },
    {
        "zhuang": "Youq gizlawz lingx cienz?",
        "zh": "在哪里领汇款？",
        "source": "textbook"
    },
    {
        "zhuang": "Youq gizlawz geiq cienz?",
        "zh": "在哪里办理汇款？",
        "source": "textbook"
    },
    {
        "zhuang": "Denswj geiq cienz baenzlawz banh?",
        "zh": "电子汇款怎么办理？",
        "source": "textbook"
    },
    {
        "zhuang": "Lingx bauhgoj lingx cienz cungj aeu sinhfwncwng.",
        "zh": "领包裹、取款都要有身份证。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou geiq fung bingzsaenq ndeu.",
        "zh": "我寄一封平信。",
        "source": "textbook"
    },
    {
        "zhuang": "Bingzsaenq fung maenz ngeih.",
        "zh": "平信一封1元2角。",
        "source": "textbook"
    },
    {
        "zhuang": "Cawx aen byuksaenq ndeu caeuq mbaw youzbiuq maenz ngeih ndeu.",
        "zh": "买一个信封和一张1元2角的邮票。",
        "source": "textbook"
    },
    {
        "zhuang": "Gvaqhauhsaenq geiq ndaw guek itbuen geijlai ngoenz daengz?",
        "zh": "国内挂号信一般要几天到？",
        "source": "textbook"
    },
    {
        "zhuang": "Sam daengz haj ngoenz couh daengz lo.",
        "zh": "3至5天就到了。",
        "source": "textbook"
    },
    {
        "zhuang": "Gij saenq geiq bae rog guek aen singhgiz daengz lwi?",
