    },
    {
        "zhuang": "Ndang mbouj cwxcaih.",
        "zh": "身体不舒服。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mwngz bae gizlawz da?",
        "zh": "你去哪里呢？",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Dawz gij cien neix daeb hwnj daeuj.",
        "zh": "把这些砖叠起来。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "—— [honghlaj] ) lai daeg lwg?",
        "zh": "你有多少个男孩？",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Song daeg lwg de gig gaenx.",
        "zh": "他的两个儿子都很勤。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gou daegbied ndiepgyaez gyoengqde.",
        "zh": "我特别喜爱他们。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De ngoenzlwenz daegdaengq daeuj yawj mwngz.",
        "zh": "他昨天特地来看望你。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mwngz ndei gvaq gou, gou mbouj daemx mwngz.",
        "zh": "你比我好，我赶不上你。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Ndaw loz miz bingz, gaej yunghrengz daengh roengz namh bae.",
        "zh": "箩筐里有瓶子，不要使劲往地上蹾。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Dawz diuz faex daengh haeuj ndaw congh bae.",
        "zh": "把棍子往洞里戳。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gou daengh mbouj hwnj mwngz.",
        "zh": "我配不上你。",
