    },
    {
        "zhuang": "Duz mou daengh gwn daengh gwn mok.",
        "zh": "猪大口大口地吃潲",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Bya daengjbyoengbyoeng.",
        "zh": "群山林立。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mbouj ndaej daengjneix guh.",
        "zh": "不能这样做。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Daengxcungq gunghyinz cungj roengzrengz.",
        "zh": "全体工人都努力。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Dawz gienh saehcingz neix hawj daengxgyoengq lwnh yawj.",
        "zh": "把这件事交给众人讨论。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Daep mou saedcaih lawx, rox cawj daengz baenz gwn.",
        "zh": "猪肝实在滑，会煮才好吃。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Guh gijmaz saeh aeu guh daengzdaej.",
        "zh": "做什么事要做彻底。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gangj vah aeu miz saedsaeh, mbouj ndaej daengzseng gangj.",
