    },
    {
        "zhuang": "Daj geij lai gyacienz?",
        "zh": "打多少价钱？",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gou daj Baekging daeuj.",
        "zh": "我从北京来。",
