        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aeu saux dengh makbug.",
        "zh": "拿竹竿捅柚子。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Dengi ancang aeu hableix.",
        "zh": "电器安装要合理。",
