    },
    {
        "zhuang": "Dawz oen deu okdaeuj.",
        "zh": "把刺挑出来。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Dawz faex deuq gij nyapnyaj neix bae.",
