    },
    {
        "zhuang": "Bya haeuj saeng lo, vaiq diem ha!",
        "zh": "鱼进罾了，快提起来呀！",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Maxlwg diem daez naj.",
