    },
    {
        "zhuang": "De najmbang, raen vunz mbouj gamj gangj vah.",
        "zh": "他害羞，见人不敢说话。",
        "source": "textbook"
    },
    {
        "zhuang": "Seizneix raeuz gwndaenj ndei raixcaix.",
        "zh": "如今咱们生活很好。",
        "source": "textbook"
    },
    {
        "zhuang": "De caen fwngzlai, luenh sij luenh veh.",
        "zh": "他手痒，乱写乱画的。",
        "source": "textbook"
    },
    {
        "zhuang": "Daxboh gou gvaqseiq lo.",
        "zh": "我的父亲逝世了。",
        "source": "textbook"
    },
    {
        "zhuang": "Ndaek caeg de byaeu lo.",
        "zh": "那贼完蛋了。",
        "source": "textbook"
    },
    {
        "zhuang": "Gij mak neix, aeu lai aeu noix, aeu hung aeu iq, caih mwngz.",
        "zh": "这些水果，要多要少，要大要小，随你便。",
        "source": "textbook"
    },
    {
        "zhuang": "Vunz gik mbouj miz gwn,",
        "zh": "人懒没有吃，",
        "source": "textbook"
    },
    {
        "zhuang": "Vunz gaenx haeux rim ranz.",
        "zh": "人勤米满屋。",
        "source": "textbook"
    },
    {
        "zhuang": "Sim ndei vunz souh gyaeu.",
        "zh": "心善人长寿",
        "source": "textbook"
    },
    {
        "zhuang": "Sim rwix vunz dai caeux.",
        "zh": "心恶人短命。",
        "source": "textbook"
    },
    {
        "zhuang": "Vaih bae song aen vanj.",
        "zh": "破了两个碗。",
        "source": "textbook"
    },
    {
        "zhuang": "Gangj lai caemh vai h bak.",
        "zh": "讲再多也白费口舌。",
        "source": "textbook"
    },
    {
        "zhuang": "Seizneix raeuz miz gwn miz daenj",
        "zh": "我们现在有吃有穿",
        "source": "textbook"
    },
    {
        "zhuang": "Gou dwg hagseng.",
        "zh": "我是学生。",
        "source": "textbook"
    },
    {
        "zhuang": "Aen hag raeuz dwg Cunghyangh Minzcuz Dayoz.",
        "zh": "我们学校是中央民族大学。",
        "source": "textbook"
    },
    {
        "zhuang": "Ngoenz neix 5 nyied 5 hauh.",
        "zh": "今天是5月5日。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou vunz Bwzgingh.",
        "zh": "我是北京人。",
        "source": "textbook"
    },
    {
        "zhuang": "Haw laeng ndwencieng.",
        "zh": "下一个集市日是正月",
        "source": "textbook"
    },
    {
        "zhuang": "De byoem bieg.",
        "zh": "他白头发。",
        "source": "textbook"
    },
    {
        "zhuang": "Aen daengq neix sam ga.",
        "zh": "这个凳子有三条腿。",
        "source": "textbook"
    },
    {
        "zhuang": "Duz vaiz haenx ndaeng vingq.",
        "zh": "那头牛鼻子破了。",
        "source": "textbook"
    },
    {
        "zhuang": "Mbouj bit cix gaeq.",
        "zh": "不是鸡就是鸭。",
        "source": "textbook"
    },
    {
        "zhuang": "Gyu mbouj gyu, lauz mbouj lauz.",
        "zh": "盐没有，油也没有。",
        "source": "textbook"
    },
    {
        "zhuang": "Ndaw ranz youzyouz mbouj miz, gyugyu mbouj miz.",
        "zh": "家里什么油盐都没有",
        "source": "textbook"
    },
    {
        "zhuang": "Hwnj caengz gwnzgwnz bae.",
        "zh": "上到最高的一层。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou buhbuh mbouj miz saek diuz.",
        "zh": "我一件衣服也没有。",
        "source": "textbook"
    },
    {
        "zhuang": "Rumzrumz fwnfwn gou cungj bae.",
        "zh": "无论风雨我都去。",
        "source": "textbook"
    },
    {
        "zhuang": "De seizneix byaekbyaek nohnoh cungj gwn ndaej.",
        "zh": "他现在什么菜都能吃了。",
        "source": "textbook"
    },
    {
        "zhuang": "Bitbit buengjbuengj cungj bwh caez lo.",
        "zh": "笔和作业本都准备好了。",
        "source": "textbook"
    },
    {
        "zhuang": "Ngaenzngaenz guhmaz ngaenz.",
        "zh": "什么钱不钱的。",
        "source": "textbook"
    },
    {
        "zhuang": "Bitbit guhmaz bit.",
        "zh": "什么笔不笔的。",
        "source": "textbook"
    },
    {
        "zhuang": "Nohnoh guhma noh.",
        "zh": "什么肉不肉的。",
        "source": "textbook"
    },
    {
        "zhuang": "Gaeqgaeq guhmaz gaeq.",
        "zh": "什么鸡不鸡的。",
        "source": "textbook"
    },
    {
        "zhuang": "Mbouj buh mbouj vaq.",
        "zh": "没有衣服。",
        "source": "textbook"
    },
    {
        "zhuang": "Mbouj boh mbouj meh",
        "zh": "没有父母。",
        "source": "textbook"
    },
    {
        "zhuang": "Mbouj fwngz mbouj ga.",
        "zh": "没有手脚",
        "source": "textbook"
    },
    {
        "zhuang": "Mbouj loz mbouj gyoi.",
        "zh": "没有箩筐和泥箕",
        "source": "textbook"
    },
    {
        "zhuang": "Byaek mbouj noh.",
        "zh": "什么菜或肉都没有。",
        "source": "textbook"
    },
    {
        "zhuang": "Bit mbouj gaeq",
        "zh": "鸡鸭都没有。",
        "source": "textbook"
    },
    {
        "zhuang": "Vaiz mbouj cwz.",
        "zh": "水牛黄牛都没有。",
        "source": "textbook"
    },
    {
        "zhuang": "Reih mbouj naz.",
        "zh": "没有田地。",
        "source": "textbook"
    },
    {
        "zhuang": "Mbouj bit cix gaeq.",
        "zh": "不是鸡就是鸭。",
        "source": "textbook"
    },
    {
        "zhuang": "Ndwn dwk gangj geij coenz vah.",
        "zh": "站着说几句话。",
        "source": "textbook"
    },
    {
        "zhuang": "Nin dwk yawj saw mbouj ndei.",
        "zh": "躺着看书不好。",
        "source": "textbook"
    },
    {
        "zhuang": "Doeg liux song bienq cihmoq.",
        "zh": "读了两遍生字。",
        "source": "textbook"
    },
    {
        "zhuang": "Gwn liux vanj haeuxcuk ndeu.",
        "zh": "吃了一碗稀饭。",
        "source": "textbook"
    },
    {
        "zhuang": "Daenj liux diuz buh moq ngawq cawx haenx.",
        "zh": "穿上了新买的那件衣服。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou yawj bonj saw neix gvaq.",
        "zh": "看过这本书。",
        "source": "textbook"
    },
    {
        "zhuang": "De bae daengz Bwzgingh gvaq.",
        "zh": "他到过北京。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou bae daengq de gvaq.",
        "zh": "我去嘱咐过他。",
        "source": "textbook"
    },
    {
        "zhuang": "Gaxgonq duz vaiz neix doek roengz dat gvaq.",
        "zh": "以前这头牛掉下过悬崖。",
        "source": "textbook"
    },
    {
        "zhuang": "Daejdaej guhmaz daej ne.",
        "zh": "哭哭什么哭呢。",
        "source": "textbook"
    },
    {
        "zhuang": "Hemqhemq guhmaz hemq ne.",
        "zh": "喊喊什么喊呢。",
        "source": "textbook"
    },
    {
        "zhuang": "Buetbuet gumaz buet ne.",
        "zh": "跑跑什么跑呢。",
        "source": "textbook"
    },
    {
        "zhuang": "Raemj ri raemjrak",
        "zh": "快点砍掉吧",
        "source": "textbook"
    },
    {
        "zhuang": "Sik si siksak",
        "zh": "快点撕掉吧",
        "source": "textbook"
    },
    {
        "zhuang": "Coeb ci coebcag",
        "zh": "快点烧掉吧",
        "source": "textbook"
    },
    {
        "zhuang": "Gwn gi gwngak",
        "zh": "快点吃掉吧",
        "source": "textbook"
    },
    {
        "zhuang": "Doemq di doemqdak",
        "zh": "赶快推倒吧",
        "source": "textbook"
    },
    {
        "zhuang": "Aeu gaiq dawz gaiq.",
        "zh": "拿了一个又一个。",
        "source": "textbook"
    },
    {
        "zhuang": "Gwn aen dawz aen.",
        "zh": "吃了一个又一个。",
        "source": "textbook"
    },
    {
        "zhuang": "Yawj bonj dawz bonj.",
        "zh": "看了一本又一本。",
        "source": "textbook"
    },
    {
        "zhuang": "Veh mbaw dawz mbaw.",
        "zh": "画了一张又一张。",
        "source": "textbook"
    },
    {
        "zhuang": "Caij go dawz go.",
        "zh": "踩了一棵又一棵。",
        "source": "textbook"
    },
    {
        "zhuang": "Haj boux haj boux guhdoih bae.",
        "zh": "每五个五个相伴而去。",
        "source": "textbook"
    },
    {
        "zhuang": "Song diuz song diuz doxcug.",
        "zh": "每两条两块地捆在一起。",
        "source": "textbook"
    },
    {
        "zhuang": "Sam daeh sam daeh cuengq loengx ndeu.",
        "zh": "每三袋三袋地放在一个箱子里。",
        "source": "textbook"
    },
    {
        "zhuang": "Roek aen boek aen guh cumh.",
        "zh": "每六个六个地做一簇",
        "source": "textbook"
    },
    {
        "zhuang": "Baez go baez go ciemz.",
        "zh": "一棵一棵地拔掉。",
        "source": "textbook"
    },
    {
        "zhuang": "Baez gaemz baez gaemz bwnq.",
        "zh": "一口一口地喂。",
        "source": "textbook"
    },
    {
        "zhuang": "Baez bonj baez bonj daeh.",
        "zh": "一本一本地搬运。",
        "source": "textbook"
    },
    {
        "zhuang": "Cug boux cug boux naeuz.",
        "zh": "一个一个地说。",
        "source": "textbook"
    },
    {
        "zhuang": "Cug gwed cug gwed daengj.",
        "zh": "一捆一捆地竖起来。",
        "source": "textbook"
    },
    {
        "zhuang": "Cug aen cug aen ndenq.",
        "zh": "一个一个地传递。",
        "source": "textbook"
    },
    {
        "zhuang": "Gij saw neix gij de.",
        "zh": "这些书是他的。",
        "source": "textbook"
    },
    {
        "zhuang": "Gij vunz haenx gou roxnaj.",
        "zh": "那些人我认识。",
        "source": "textbook"
    },
    {
        "zhuang": "Gij doih haenx mbouj rox youq lawz.",
        "zh": "那些同伴不知何在。",
        "source": "textbook"
    },
    {
        "zhuang": "Raix gij doxgaiq ndaw daeh okdaeuj.",
        "zh": "把袋子里的东西倒出来。",
        "source": "textbook"
    },
    {
        "zhuang": "Gag gou bae.",
        "zh": "只有我去。",
        "source": "textbook"
    },
    {
        "zhuang": "Gag de youq.",
        "zh": "仅有他在。",
        "source": "textbook"
    },
    {
        "zhuang": "Gag mwngz mbouj daeuj.",
        "zh": "只有你没来。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz gag bae.",
        "zh": "你自己去。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou gag guh.",
        "zh": "我自己做。",
        "source": "textbook"
    },
    {
        "zhuang": "De gag ninz haemhlwenz.",
        "zh": "他昨晚自己睡的。",
        "source": "textbook"
    },
    {
        "zhuang": "Danghnaeuz bae cix ndei.",
        "zh": "若能去就好。",
        "source": "textbook"
    },
    {
        "zhuang": "Mboujdan gou lij de.",
        "zh": "不仅有我还有他。",
        "source": "textbook"
    },
    {
        "zhuang": "De ak gvaq gou.",
        "zh": "他比我强。",
        "source": "textbook"
    },
    {
        "zhuang": "Go faex neix hung gvaq go haenx haujlai.",
        "zh": "这棵树比那棵树大许多。",
        "source": "textbook"
    },
    {
        "zhuang": "De sang gvaq gou.",
        "zh": "他比我高。",
        "source": "textbook"
    },
    {
        "zhuang": "Lwgnyez neix roxsoq gvaq lwg de.",
        "zh": "这个孩子比那个孩子懂事。",
        "source": "textbook"
    },
    {
        "zhuang": "Youz mwngz gangj.",
        "zh": "由你怎么说。",
        "source": "textbook"
    },
    {
        "zhuang": "Riengz diuz roen neix bae.",
        "zh": "沿着这条路走去。",
        "source": "textbook"
    },
    {
        "zhuang": "Aenvih de ninzndaek lo.",
        "zh": "因为他睡着了。",
        "source": "textbook"
    },
    {
        "zhuang": "Bae cimh de.",
        "zh": "向他走去。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz ciuq guh couh ndaej lo.",
        "zh": "你跟着做就行了。",
        "source": "textbook"
    },
    {
        "zhuang": "Deng de doeg lo.",
        "zh": "轮到他念了。",
        "source": "textbook"
    },
    {
        "zhuang": "De laeng gou ciq cib maenz ngaenz.",
        "zh": "她跟我借十块钱。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz song duz neix gai bae.",
        "zh": "把这两只卖了。",
        "source": "textbook"
    },
    {
        "zhuang": "Aeu aen daengq ndeu daeuj hawj gou.",
        "zh": "拿个凳子来给我。",
        "source": "textbook"
    },
    {
        "zhuang": "Doiq mwngz caeuq gou naeuz.",
        "zh": "对我和你说。",
        "source": "textbook"
    },
    {
        "zhuang": "Vih lauxsae caeuq hagseng fuzvu.",
        "zh": "为师生服务。",
        "source": "textbook"
    },
    {
        "zhuang": "Caeuq beixnuengx ok rog.",
        "zh": "和兄弟一起外出。",
        "source": "textbook"
    },
    {
        "zhuang": "Hawj bitgaeq maj ndaej vaiq.",
        "zh": "让鸡鸭长得快。",
        "source": "textbook"
    },
    {
        "zhuang": "Daj ngoenzneix bae.",
        "zh": "从今往后。",
        "source": "textbook"
    },
    {
        "zhuang": "Hawj boux'wn aeu daeuj.",
        "zh": "叫别人拿来。",
        "source": "textbook"
    },
    {
        "zhuang": "Daiq nuengx gou guhcaemz.",
        "zh": "带着我弟玩耍。",
        "source": "textbook"
    },
    {
        "zhuang": "Deng caxbyaek heh sieng.",
        "zh": "被菜刀拉伤了。",
        "source": "textbook"
    },
    {
        "zhuang": "Daiq cihsaw cungj sij mbouj baenz.",
        "zh": "连字都写不好。",
        "source": "textbook"
    },
    {
        "zhuang": "Cawz ndaem naz lij gai byaek.",
        "zh": "除了种田还卖菜。",
        "source": "textbook"
    },
    {
        "zhuang": "Daj haeuj hag doxma.",
        "zh": "自入学以来。",
        "source": "textbook"
    },
    {
        "zhuang": "Beij dawz cae ndei.",
        "zh": "比种地的好。",
        "source": "textbook"
    },
    {
        "zhuang": "Yiengq baihdoeng bae.",
        "zh": "向东去。",
        "source": "textbook"
    },
    {
        "zhuang": "Daj baihsae ma.",
        "zh": "从西边回来。",
        "source": "textbook"
    },
    {
        "zhuang": "Youz baihgwnz daeuj.",
        "zh": "由上边来。",
        "source": "textbook"
    },
    {
        "zhuang": "Riengz henzdah byaij.",
        "zh": "沿着河边走。",
        "source": "textbook"
    },
    {
        "zhuang": "Hawj bouxlawz yawj.",
        "zh": "给谁看？",
        "source": "textbook"
    },
    {
        "zhuang": "Aeu bonjsaw hawj gou.",
        "zh": "给我拿本书。",
        "source": "textbook"
    },
    {
        "zhuang": "Ndwn youq baihnaj.",
        "zh": "站在前面。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou youq ranz.",
        "zh": "我在家。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz daengz ranz seizlawz?",
        "zh": "你何时到家？",
        "source": "textbook"
    },
    {
        "zhuang": "Daengz baihrog bae naengh.",
        "zh": "到外面去坐着。",
        "source": "textbook"
    },
    {
        "zhuang": "De yungh cienz lai lwi?",
        "zh": "他花钱花的多吗？",
        "source": "textbook"
    },
    {
        "zhuang": "Yungh gonjbit neix sij saw.",
        "zh": "用这支笔写字。",
        "source": "textbook"
    },
    {
        "zhuang": "Sou beij gijmaz?",
        "zh": "你们比什么？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz beij de oiq.",
        "zh": "你比他年轻。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou byaij gvaq laeng mwngz.",
        "zh": "我从你家经过。",
        "source": "textbook"
    },
    {
        "zhuang": "Yaek ginggvaq mwngz hawj cij ndaej.",
        "zh": "须经你允许才行。",
        "source": "textbook"
    },
    {
        "zhuang": "Bouxhung caeuq bouxiq cungj bae ndaej.",
        "zh": "大人和小孩都能去。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou caeuq daegbeix youq ranz yawj saw.",
        "zh": "我和哥哥在家看书。",
        "source": "textbook"
    },
    {
        "zhuang": "Moulwg riengz moumeh bae ndaw reih.",
        "zh": "小猪跟着母猪去地里。",
        "source": "textbook"
    },
    {
        "zhuang": "De gai byaek youhcaiq gai noh.",
        "zh": "他卖菜又卖肉。",
        "source": "textbook"
    },
    {
        "zhuang": "Aenmak aen dem aen doek roengz loz daeuj.",
        "zh": "水果一个接一个地掉到箩筐里。",
        "source": "textbook"
    },
    {
        "zhuang": "De youq gizneix ngoenz dem ngoenz.",
        "zh": "他在这儿呆了一天又一天。",
        "source": "textbook"
    },
    {
        "zhuang": "Fwn doek roxnaeuz mbouj doek cungj ityiengh.",
        "zh": "下不下雨都一样。",
        "source": "textbook"
    },
    {
        "zhuang": "Ngoenzneix daeuj cixnaeuz ngoenzcog daeuj?",
        "zh": "今天来还是明天来？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz bae hixnaeuz mbouj bae cungj yaek naeuz hawj baengxyoux gou nyi.",
        "zh": "你去不去都要告诉我的朋友。",
        "source": "textbook"
    },
    {
        "zhuang": "De mboujdan bang mwngz, vanzlij bang gou.",
        "zh": "他不但帮助你，还帮助我。",
        "source": "textbook"
    },
    {
        "zhuang": "De daemq caemhcaiq biz.",
        "zh": "他个儿矮而且胖。",
        "source": "textbook"
    },
    {
        "zhuang": "Daeglwg de mboujdan rox dwk lamzgiuz、binghbanghgiuz, vanzlij rox dajcaemx.",
        "zh": "他儿子不但会打篮球、乒乓球，还会游泳。",
        "source": "textbook"
    },
    {
        "zhuang": "Raeuz hung doxdoengz, hoeng gou gvai gvaq de.",
        "zh": "我们一般大，但我比他聪明。",
        "source": "textbook"
    },
    {
        "zhuang": "De yienznaeuz iq, hoeng ak gwn raixcaix.",
        "zh": "他虽然小，但是很能吃。",
        "source": "textbook"
    },
    {
        "zhuang": "Yienznaeuz gou mbouj youq ranz, hoeng bouxlawz naeuzdingq mbouj naeuzdingq gou cungj rox.",
        "zh": "虽然我不在家，但谁听话不听话我都知道。",
        "source": "textbook"
    },
    {
        "zhuang": "Boux boux cungj siengj bae yawj heiq, mboujgoq mizmbangj boux yaek hwnj dangz.",
        "zh": "人人都想去看戏，不过有些人还要上课。",
        "source": "textbook"
    },
    {
        "zhuang": "Danghnaeuz de mbouj youq ranz couh suenq lo.",
        "zh": "如果她不在家就算了。",
        "source": "textbook"
    },
    {
        "zhuang": "Youzcaih vunz baenzlawz gangj cungj mbouj lau.",
        "zh": "任凭别人怎么说都不怕。",
        "source": "textbook"
    },
    {
        "zhuang": "Denva mbouj ciep, yienzlai de mbouj youq ranz.",
        "zh": "电话没人接，原来他不在家。",
        "source": "textbook"
    },
    {
        "zhuang": "Mboujlwnh byawz cungj mbouj ndaej ok rog hag bae.",
        "zh": "不论谁都不能出校园外。",
        "source": "textbook"
    },
    {
        "zhuang": "Aenvih guh hong dwgrengz baenz bingh naek, sojyij de hwnq mbouj ndaej lo.",
        "zh": "因为劳成疾，所以他起不来了。",
        "source": "textbook"
    },
    {
        "zhuang": "Gyoengqde doeksaet yat, mwngz buet gou ndoj, hauq vut aen gyoh roengzdaeuj.",
        "zh": "她大吃一惊，便东躲西藏，所以丢下了一个葫芦。",
        "source": "textbook"
    },
    {
        "zhuang": "Caeklaiq mwngz guh ndaej ndei, mboujne couh deng daxboh ndaq lo.",
        "zh": "幸亏你做得好，不然就会被父亲骂了。",
        "source": "textbook"
    },
    {
        "zhuang": "Ndaw ranz yienznaeuz vunz mbouj lai, hoeng caemh roxnyinh nauhyied raixcaix.",
        "zh": "家里人虽不多，但也觉得十分热闹。",
        "source": "textbook"
    },
    {
        "zhuang": "Yienznaeuz haujlai bi mbouj raen naj, hoeng gou lij ndaej geiq gij yiengh de.",
        "zh": "虽然多年没见面，但我还能记住她的模样。",
        "source": "textbook"
    },
    {
        "zhuang": "Caenh'aeu raeuz roengz goengfou, couh hag ndaej ndei.",
        "zh": "只要我们下了工夫，就会学得好。",
        "source": "textbook"
    },
    {
        "zhuang": "Danghnaeuz de mbouj daeuj, gou couh gag bae.",
        "zh": "如果他不来，我就自己去。",
        "source": "textbook"
    },
    {
        "zhuang": "Seizneix caeuq seizgonq mbouj doxdoengz.",
        "zh": "现在跟以前不一样。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou caeuq de guhdoih bae laeng mwngz.",
        "zh": "我和他一起去你家。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou caeuq de cungj dwg hagseng.",
        "zh": "我和他都是学生。",
        "source": "textbook"
    },
    {
        "zhuang": "De caeuq gou cungj dwg hagseng.",
        "zh": "他和我都是学生。",
        "source": "textbook"
    },
    {
        "zhuang": "Caeuq de bae gag.",
        "zh": "和他上学校。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou bae caeuq de doxyaeng.",
        "zh": "我去和他商量。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou ninz dwk hwet in lo.",
        "zh": "我睡得腰都疼了。",
        "source": "textbook"
    },
    {
        "zhuang": "De in dwk raemxda rih.",
        "zh": "他疼得流了眼泪。",
        "source": "textbook"
    },
    {
        "zhuang": "De deng dub dwk daejngaxngax.",
        "zh": "他被打得哇哇哭。",
        "source": "textbook"
    },
    {
        "zhuang": "De nyaengq dwk baenqloenxloenx.",
        "zh": "他忙得团团转。",
        "source": "textbook"
    },
    {
        "zhuang": "Aen mak neix ngwh dwk hoengzfwgfwg.",
        "zh": "这个水果熟得深红深红的。",
        "source": "textbook"
    },
    {
        "zhuang": "De ninz dwk yawj saw.",
        "zh": "他躺着看书。",
        "source": "textbook"
    },
    {
        "zhuang": "Raeuz naengh dwk gangj goj.",
        "zh": "我们坐着说故事。",
        "source": "textbook"
    },
    {
        "zhuang": "De riu dwk yawj gou.",
        "zh": "她笑着看我。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou bae laeng de gvaq.",
        "zh": "我去过他家。",
        "source": "textbook"
    },
    {
        "zhuang": "Dingq gienh saeh neix gvaq.",
        "zh": "听说过这件事。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou son sawcuengh de gvaq.",
        "zh": "我教过他壮文。",
        "source": "textbook"
    },
    {
        "zhuang": "Yungh bae haj maenz ngaenz.",
        "zh": "花了五块钱。",
        "source": "textbook"
    },
    {
        "zhuang": "Sik bae song mbaw ceij.",
        "zh": "撕了两张纸。",
        "source": "textbook"
    },
    {
        "zhuang": "Gwn bae vanj haeux ndeu.",
        "zh": "吃了一碗饭。",
        "source": "textbook"
    },
    {
        "zhuang": "Bae ndaej yaepndeu lo.",
        "zh": "去了一会儿了。",
        "source": "textbook"
    },
    {
        "zhuang": "Naengh ndaej buenq diemj lo.",
        "zh": "坐了半小时了。",
        "source": "textbook"
    },
    {
        "zhuang": "Doeg ndaej song bi saw.",
        "zh": "读了两年书。",
        "source": "textbook"
    },
    {
        "zhuang": "Daxmeh gou mbouj caengz doeg saw gvaq.",
        "zh": "我母亲未曾读过书。",
        "source": "textbook"
    },
    {
        "zhuang": "De bae haw gai byaek gvaq.",
        "zh": "他去集市卖过菜。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz yaek daenj haiz dwk bae cij baenz.",
        "zh": "你要穿了鞋去才行。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou gwn haeux imq dwk menh bae cimh mwngz.",
        "zh": "我吃饱了饭再去找你。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz daet byoem dinj dwk engqgya gyaeu.",
        "zh": "你头发剪短了更漂亮。",
        "source": "textbook"
    },
    {
        "zhuang": "Vaiz duh gou haemhlwenz mbouj raen lo.",
        "zh": "我的牛昨晚不见了。",
        "source": "textbook"
    },
    {
        "zhuang": "Vaq duh mwngz dak hawq caengz?",
        "zh": "你的裤子晒干了吗？",
        "source": "textbook"
    },
    {
        "zhuang": "Ranz duh mwngz hab coihcoih lo.",
        "zh": "你的房子该修一修了。",
        "source": "textbook"
    },
    {
        "zhuang": "Duh mwngz cuengq youq gwnz daiz.",
        "zh": "你的放在桌子上。",
        "source": "textbook"
    },
    {
        "zhuang": "Gwn duh mwngz gonq, cij gwn duh de laeng.",
        "zh": "先吃你的，再吃他的。",
        "source": "textbook"
    },
    {
        "zhuang": "Duh gou lumz youq ndaw ranz lo.",
        "zh": "我的忘在家里了。",
        "source": "textbook"
    },
    {
        "zhuang": "Aen mauh neix duh mwngz.",
        "zh": "这个帽子是你的。",
        "source": "textbook"
    },
    {
        "zhuang": "Bonj saw gwnz daiz duh gou.",
        "zh": "桌上的书是我的。",
        "source": "textbook"
    },
    {
        "zhuang": "Aen gaet hoengz haenx duh de.",
        "zh": "那个红扣子是她的。",
        "source": "textbook"
    },
    {
        "zhuang": "Duzvaiz henzmieng duh boh gou.",
        "zh": "河边的牛是我爸的。",
        "source": "textbook"
    },
    {
        "zhuang": "Saw umj aeu roxnaeuz riuj aeu ma ranz?",
        "zh": "书抱着还是提着回家？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz naengh aeu roxnaeuz ndwn aeu?",
        "zh": "你想坐着还是站着？",
        "source": "textbook"
    },
    {
        "zhuang": "Bae laeng daxgoeng byaij aeu roxnaeuz naengh ci aeu?",
        "zh": "要去爷爷家，走着去还是坐车去？",
        "source": "textbook"
    },
    {
        "zhuang": "Gij saw neix daj aeu roxnaeuz sij aeu?",
        "zh": "这些字用打字还是手写？",
        "source": "textbook"
    },
    {
        "zhuang": "Mbaenq faex neix gawq aeu roxnaeuz raemj aeu?",
        "zh": "这块木头锯着好还是砍好？",
        "source": "textbook"
    },
    {
        "zhuang": "De naengh dwk gangjbyodbyod henz daiz.",
        "zh": "他在桌子边坐着不停地说话。",
        "source": "textbook"
    },
    {
        "zhuang": "De ciengzseiz ninz dwk yawj saw.",
        "zh": "他经常躺着看书。",
        "source": "textbook"
    },
    {
        "zhuang": "Gven aen'dou ndaet ndaet dwk.",
        "zh": "紧紧地关着门。",
        "source": "textbook"
    },
    {
        "zhuang": "Diemj aen'daeng rongh rongh dwk.",
        "zh": "把灯点得亮亮的。",
        "source": "textbook"
    },
    {
        "zhuang": "Gwn ndaej song vanj haeux.",
        "zh": "吃了两碗饭。",
        "source": "textbook"
    },
    {
        "zhuang": "Guh ndaej song aen daenq.",
        "zh": "做了两个凳子。",
        "source": "textbook"
    },
    {
        "zhuang": "Rap ndaej rap raemx ndeu.",
        "zh": "挑了一担水。",
        "source": "textbook"
    },
    {
        "zhuang": "Bae ndaej song ngoenz.",
        "zh": "去了两天。",
        "source": "textbook"
    },
    {
        "zhuang": "Buet ndaej seiq hob.",
        "zh": "跑了四圈。",
        "source": "textbook"
    },
    {
        "zhuang": "Roq ndaej haj baez gyong.",
        "zh": "敲了五次鼓。",
        "source": "textbook"
    },
    {
        "zhuang": "Hwnj ndaej caengz haemq gwnz.",
        "zh": "爬到更上一层。",
        "source": "textbook"
    },
    {
        "zhuang": "Cawx ndaej byaek couh ma.",
        "zh": "买到菜就回来。",
        "source": "textbook"
    },
    {
        "zhuang": "Nyaeb ndaej doxgaiq couh gyau.",
        "zh": "捡到东西就上交。",
        "source": "textbook"
    },
    {
        "zhuang": "Laemh ndaej duzgoep ma gwn laeuj.",
        "zh": "摸到青蛙来下酒。",
        "source": "textbook"
    },
    {
        "zhuang": "Duzmou neix miz song bak gaen bw.",
        "zh": "这头猪可能有两百斤重呢。",
        "source": "textbook"
    },
    {
        "zhuang": "Raeuz ngoenzlaeng doxcaeuq bae haw bw.",
        "zh": "我们后天一起去赶集啊。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz yaek daeuj heuh gou bw.",
        "zh": "你要来叫我啊。",
        "source": "textbook"
    },
    {
        "zhuang": "Haemhneix ma ranz haemq vaiq bw.",
        "zh": "今晚要早些回家啊。",
        "source": "textbook"
    },
    {
        "zhuang": "Gaej deng gij doxgaiq ndaw loengz bw.",
        "zh": "别碰箱子里的东西啊。",
        "source": "textbook"
    },
    {
        "zhuang": "Faen mbouj ndaej cwz gaej ienq gou bw.",
        "zh": "分不到黄牛别埋怨我啊。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz mbouj ndaej naeuz daxboh nyi bw.",
        "zh": "你不能告诉爸爸啊！",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz gaej nyaeuh gou bw.",
        "zh": "你别欺骗我啊！",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz ndaej hoengq couh daeuj guhcaemz nw.",
        "zh": "你有空就来玩啊。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz bae hag gaej lumz daiq suhbauh nw.",
        "zh": "你上学别忘了带书包啊。",
        "source": "textbook"
    },
    {
        "zhuang": "Cawx gonj bit ndeu ma hawj gou nw.",
        "zh": "买一支笔回来给我啊。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz caemh bae laeng de gwn haeux nw?",
        "zh": "你也去他家吃饭吗？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz ngoencog mbouj youq ranz nw?",
        "zh": "你明天不在家吗？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz yaek daeuj laeng gou nw?",
        "zh": "你要来我家吗？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz ngoenzneix bae hag mbouj?Bae ha.",
        "zh": "你今天去学校不？去。",
        "source": "textbook"
    },
    {
        "zhuang": "Laeng mwngz miz gaeq lai mbouj?Miz ha.",
        "zh": "你家有很多鸡吗？有。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz bae mbanj lwi?Bae ha.",
        "zh": "你去亲戚家吗？去。",
        "source": "textbook"
    },
    {
        "zhuang": "Vaiq bae ha!Mbwn laep roen mbouj baenz byaij.",
        "zh": "快去！天黑路不好走。",
        "source": "textbook"
    },
    {
        "zhuang": "Vaiq daeuj ha!Miz vunz doek roengz daemz lo.",
        "zh": "快来！有人掉到池塘里了。",
        "source": "textbook"
    },
    {
        "zhuang": "Ok bae ha! Yaek gven gyausiz lo.",
        "zh": "出去！要关教室了。",
        "source": "textbook"
    },
    {
        "zhuang": "Gangj ha! Mboujne gou cuengq lo.",
        "zh": "说！要不然我放下了。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz ra bouxlawz ha?",
        "zh": "你找谁啊？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz dwg vunz Gvangjsix ha?",
        "zh": "你是广西人吗？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz haengj gwn mangjgoj ha?",
        "zh": "你喜欢吃芒果吗？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz haemhneix bae yawj denyingj lwi?",
        "zh": "你今晚去看电影吗？",
        "source": "textbook"
    },
    {
        "zhuang": "Gou caeuq mwngz guhdoih bae baenz lwi?",
        "zh": "我和你做伴去好吗？",
        "source": "textbook"
    },
    {
        "zhuang": "De daeuj laeng mwngz gvaq la?",
        "zh": "他来过你家啦？",
        "source": "textbook"
    },
    {
        "zhuang": "De bae haq la?",
        "zh": "她出嫁啦？",
        "source": "textbook"
    },
    {
        "zhuang": "De haetneix ma ranz la?",
        "zh": "她今早回家啦？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz bae dajcaemx lwi?Mbouj bae law.",
        "zh": "你去不去游泳？不去。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz naeuz de daeuj mbouj?Mbouj daeuj law.",
        "zh": "你说她来不来？不来。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz gwn haeux mbouj gwn?Mbouj gwn law.",
        "zh": "你吃饭不吃？不吃。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou daek vanj haeux hawj mwngz ba?Mbouj law.",
        "zh": "我盛碗饭给你吧？不。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou gwn vanj haeux dem.",
        "zh": "我再吃一碗饭。",
        "source": "textbook"
    },
    {
        "zhuang": "Nit lo, daenj diuz buh dem.",
        "zh": "天冷了，多穿一件衣服。",
        "source": "textbook"
    },
    {
        "zhuang": "Ngah bak lai, hawj aen mak dem.",
        "zh": "嘴太谗了，再给一个水果。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz mbouj siengj dingq diuzgo dem?",
        "zh": "你不想再听一首歌？",
        "source": "textbook"
    },
    {
        "zhuang": "Ndwn dwk! Gaej doengh!",
        "zh": "站住，别动！",
        "source": "textbook"
    },
    {
        "zhuang": "Saeg seuq dwk!, mboujne hoj yawj yaek dai.",
        "zh": "洗干净！要不难看死了。",
        "source": "textbook"
    },
    {
        "zhuang": "Hen dwk!Lau vunz dwk dawz bae gwn.",
        "zh": "守住！以防被别人打了吃掉。",
        "source": "textbook"
    },
    {
        "zhuang": "Re dwk! dangqnaj miz u raemx ndeu.",
        "zh": "当心！前面有一摊水。",
        "source": "textbook"
    },
    {
        "zhuang": "Rumz baek rem lai, gven aencueng bae.",
        "zh": "北风太猛，请把窗户关上。",
        "source": "textbook"
    },
    {
        "zhuang": "Gwn vanj haeux liux bae, gaej lw.",
        "zh": "把这碗饭吃完了，别剩下。",
        "source": "textbook"
    },
    {
        "zhuang": "Daet byoem dinj bae, raez cix hwngq lai.",
        "zh": "把头发剪短了，长了太热。",
        "source": "textbook"
    },
    {
        "zhuang": "Boux vunz ndwn haenx sangyoegyoeg bae.",
        "zh": "站着的那个人个子高高的。",
        "source": "textbook"
    },
    {
        "zhuang": "Aen loengz neix naek dangqmaz bae.",
        "zh": "这个箱子很重的。",
        "source": "textbook"
    },
    {
        "zhuang": "Duzngwz de dub haenx raezrangrang bae.",
        "zh": "他打的那条蛇长长的。",
        "source": "textbook"
    },
    {
        "zhuang": "Duzvaiz haemhlwenz gwn bae baenz gaiq naz.",
        "zh": "牛昨晚吃掉了整块田的水稻。",
        "source": "textbook"
    },
    {
        "zhuang": "De daj laeng gou ciq bae sam bak maenz ngaenz.",
        "zh": "他从我这儿借了三百元钱。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz gwn gonq, gou mbouj iek geijlai.",
        "zh": "你吃吧，我不怎么饿。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz youq gonq, gou bae heuh de gvaq daeuj.",
        "zh": "你等着吧，我去把她叫来。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou bae ndaw reih aeu byaek gonq.",
        "zh": "我到地里摘菜了。",
        "source": "textbook"
    },
    {
        "zhuang": "Haemh lo, gou gag bae ninz gonq.",
        "zh": "晚了，我自己睡觉去了。",
        "source": "textbook"
    },
    {
        "zhuang": "Hek yaek daeuj lo, gou ma ranz gonq.",
        "zh": "客人要来了，我回去了。",
        "source": "textbook"
    },
    {
        "zhuang": "Mbatlaeng gonq, gou menh bae laeng mwngz.",
        "zh": "以后吧，我再去你家。",
        "source": "textbook"
    },
    {
        "zhuang": "Haetcog gonq, gou menh naeuz mwngz yi.",
        "zh": "明天吧，我再告诉你。",
        "source": "textbook"
    },
    {
        "zhuang": "Ngoenzsinghgiz gonq, gou menh daeuj bang mwngz.",
        "zh": "星期天吧，我再来帮助你。",
        "source": "textbook"
    },
    {
        "zhuang": "Yaepdi gonq, raeuz caez ok bae guhcaemz.",
        "zh": "过一会儿吧，我们一起出去玩。",
        "source": "textbook"
    },
    {
        "zhuang": "Lwg hwi, gaej caeuq vunz doxdaj nw.",
        "zh": "孩子，别和人家打架啊。",
        "source": "textbook"
    },
    {
        "zhuang": "Boh hwi, haemhneix cawj byaek maz baenz?",
        "zh": "爸，今晚做什么菜好呢？",
        "source": "textbook"
    },
    {
        "zhuang": "Genmingz hwi, haemhneix doxcaeuq gwn laeuj bw.",
        "zh": "建明，今晚一起喝酒啊。",
        "source": "textbook"
    },
    {
        "zhuang": "Yienghneix mwngz couh vaiq daeuj lu.",
        "zh": "这样，你就快来吧。",
        "source": "textbook"
    },
    {
        "zhuang": "Yaek ma ninz cix bae lu.",
        "zh": "想回去睡觉就去吧。",
        "source": "textbook"
    },
    {
        "zhuang": "Yaek gwn cix gwn lu.",
        "zh": "想吃就吃吧。",
        "source": "textbook"
    },
    {
        "zhuang": "Laeng mwngz miz maknganx lwi?Miz liux.",
        "zh": "你家有龙眼吗？有啊！",
        "source": "textbook"
    },
    {
        "zhuang": "Gou haemhneix bae cimh mwngz baenz lwi?Baenz liux.",
        "zh": "我今晚去找你好吗？好啊！",
        "source": "textbook"
    },
    {
        "zhuang": "Hawj de daeuj dwk geiz mbouj? Hawj liux.",
        "zh": "让他来打牌吗？让啊。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz cix yienghlawz guhfap ye?",
        "zh": "你是怎样做的呢？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz caeg mbwn cix baeq caeg ndaej ye?",
        "zh": "你“偷天”却怎么个偷法呢？",
        "source": "textbook"
    },
    {
        "zhuang": "De haemhneix daeuj mbouj ye?",
        "zh": "他今晚来不来呢？",
        "source": "textbook"
    },
    {
        "zhuang": "Vihmaz heuh sam gaen roek liengx ne?",
        "zh": "为何叫“三斤六两”呢？",
        "source": "textbook"
    },
    {
        "zhuang": "De youq mbouj youq ranz ne?",
        "zh": "他是否在家呢？",
        "source": "textbook"
    },
    {
        "zhuang": "Yiengh ne, raeuz couh daengz ndaej gib lo.",
        "zh": "这样的话，我们就能及时到了。",
        "source": "textbook"
    },
    {
        "zhuang": "Mbouj ne, de couh deng boiz ngaenz lo.",
        "zh": "不然的话，他就要赔钱了。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou naeuz ngoenzneix fwn doek mbouj loek ne.",
        "zh": "我说今天下雨没错的。",
        "source": "textbook"
    },
    {
        "zhuang": "Aen doengzgyaek neix baizdui dwk cawx cijndaej ne.",
        "zh": "这个宝竹筒排了队才买到的。",
        "source": "textbook"
    },
    {
        "zhuang": "Ne! de naengh youq mwnqhaenx.",
        "zh": "看！她坐在那儿。",
        "source": "textbook"
    },
    {
        "zhuang": "Ne! ndaw ranz mbouj miz saek boux.",
        "zh": "看！家里一个人都没有。",
        "source": "textbook"
    },
    {
        "zhuang": "De bae yienhsingz banh saeh dinghlo.",
        "zh": "他可能去县城办事了。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou bi'gyai youq Namzningz raen de dinghlo.",
        "zh": "我可能前年在南宁见她过。",
        "source": "textbook"
    },
    {
        "zhuang": "De haemhlwenz ma daengz ranz dinghlo.",
        "zh": "他可能是昨晚回到家的。",
        "source": "textbook"
    },
    {
        "zhuang": "Daxboh hawj de bae cawx laeuj dinghlo.",
        "zh": "爸爸可能让他去打酒了。",
        "source": "textbook"
    },
    {
        "zhuang": "Ngoenzcog deng mwngz guh cizyizsaengh lubw.",
        "zh": "明天轮到你做值日生了。",
        "source": "textbook"
    },
    {
        "zhuang": "Gvaq song ngoenz couh daengz cieng lubw.",
        "zh": "过两天就到春节了。",
        "source": "textbook"
    },
    {
        "zhuang": "De ngonzrawz couh daeuj daengz laeng mwngz lubw.",
        "zh": "他后天就到你家了。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou ngoenzlwenz aeu fagseiz hawj daboh mwngz lubw.",
        "zh": "我昨天把钥匙给你父亲了",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz doeg bonj saw neix gvaq lunw?",
        "zh": "你读过这本书了是吗？",
        "source": "textbook"
    },
    {
        "zhuang": "De ngoenzlwenz bae laeng gou lunw?",
        "zh": "他昨天去我家了是吗？",
        "source": "textbook"
    },
    {
        "zhuang": "Sou haemhlwenz haeuj lueg dwk nyaen lunw?",
        "zh": "你们昨晚进山打猎了是吗？",
        "source": "textbook"
    },
    {
        "zhuang": "Niq hwi, hai dou luvei.",
        "zh": "孩子，开门吧。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz vaiq daeuj luvei.",
        "zh": "你快来吧。",
        "source": "textbook"
    },
    {
        "zhuang": "Bae heuh de ma luvei.",
        "zh": "去叫她回来吧。",
        "source": "textbook"
    },
    {
        "zhuang": "Roengzrengz guh hong luvei.",
        "zh": "努力干活吧。",
        "source": "textbook"
    },
    {
        "zhuang": "De ngoenzneix youq ranz yietbaeg luba.",
        "zh": "他今天应该在家休息吧。",
        "source": "textbook"
    },
    {
        "zhuang": "Vunz cungj daeuj caez luba.",
        "zh": "人应该都到齐了。",
        "source": "textbook"
    },
    {
        "zhuang": "De bae haw cawx byaek luba.",
        "zh": "她应该到集市买菜了。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou lumz gonjbit youq ranz luba.",
        "zh": "我应该是把笔忘在家里了。",
        "source": "textbook"
    },
    {
        "zhuang": "Haemhlwenz duzma de raeuq mwngz luba?",
        "zh": "昨晚他的狗对你叫了吧？",
        "source": "textbook"
    },
    {
        "zhuang": "De bae mbouj daiq hab, mwngz bae balu.",
        "zh": "他去不太合适，你去吧。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz hawj gou son gyoengqde ciengq go balu.",
        "zh": "你让我教他们唱歌吧。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou ngoencog ma ranz gavqciet balu.",
        "zh": "我明天回家过节吧。",
        "source": "textbook"
    },
    {
        "zhuang": "Fwn doekrara, raeuz caj fwn dingz menh bae balu.",
        "zh": "雨在哗哗地下，我们等雨停了再去吧。",
        "source": "textbook"
    },
    {
        "zhuang": "Rumz bongj daeuj ganjfaex couh raek satli.",
        "zh": "风吹来树干就折断了。",
        "source": "textbook"
    },
    {
        "zhuang": "Hawj de guh, de mbouj guh satli.",
        "zh": "叫他做，他不做。",
        "source": "textbook"
    },
    {
        "zhuang": "Fwn doek le roen myag lai laemx satli.",
        "zh": "下雨路太滑而摔倒的。",
        "source": "textbook"
    },
    {
        "zhuang": "Yiengh haenx mwngz naeuz satli.",
        "zh": "那你就说吧。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou aeu gang ngaenz ndeu hawj mwngz dawz ma satlo.",
        "zh": "我把一缸的银子给你拿回去算了。",
        "source": "textbook"
    },
    {
        "zhuang": "De faen gya ndaej duz raeu he satlo.",
        "zh": "他分家时仅仅得到一只虱子。",
        "source": "textbook"
    },
    {
        "zhuang": "Gag gou bae hag satlo.",
        "zh": "只有我一个人上学。",
        "source": "textbook"
    },
    {
        "zhuang": "Hawj guh gijmaz gou cix caeuq mwngz guh satlo.",
        "zh": "叫我做什么我就给你做什么。",
        "source": "textbook"
    },
    {
        "zhuang": "Da laep lo, gou ma ninz halu.",
        "zh": "我困了回去睡觉了。",
        "source": "textbook"
    },
    {
        "zhuang": "Raeuz bae laj go rungz haenx baez yiet ndeu halu.",
        "zh": "我们到那棵榕树下歇一会儿吧。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz caeuq de caemh daiz halu?",
        "zh": "你和他同桌好吗？",
        "source": "textbook"
    },
    {
        "zhuang": "Gou rap raemx ma hawj mwngz halu?",
        "zh": "我挑水回来给你好吗？",
        "source": "textbook"
    },
    {
        "zhuang": "Gaiq neix, dwg gou caeg mbwn ndaej luga.",
        "zh": "这个嘛，是我偷天得来的。",
        "source": "textbook"
    },
    {
        "zhuang": "Fwn doek daengz cij bae dawzcae luga.",
        "zh": "天下雨了，才去耕种的。",
        "source": "textbook"
    },
    {
        "zhuang": "Cietheiq daengz mwngz cix ndaem gode luga.",
        "zh": "什么节气，你就种什么植物。",
        "source": "textbook"
    },
    {
        "zhuang": "Gaemz dog gwn ndaej haj vanj bae.",
        "zh": "一口能吃五碗呢。",
        "source": "textbook"
    },
    {
        "zhuang": "De gwed ndaej song bak gaen bae.",
        "zh": "他能扛两百斤重呢。",
        "source": "textbook"
    },
    {
        "zhuang": "Buet vaiq gvaq giceh bae.",
        "zh": "比汽车跑得还快呢。",
        "source": "textbook"
    },
    {
        "zhuang": "Aeu bae song fag liemz.",
        "zh": "拿了两把镰刀。",
        "source": "textbook"
    },
    {
        "zhuang": "Raek bae song go faex.",
        "zh": "折断了两棵树。",
        "source": "textbook"
    },
    {
        "zhuang": "Vaih bae aen eij ndeu.",
        "zh": "弄坏了一把椅子。",
        "source": "textbook"
    },
    {
        "zhuang": "Dongj bae song moux naz.",
        "zh": "冲毁了两亩水田。",
        "source": "textbook"
    },
    {
        "zhuang": "Bouxlawz gwn bae aen dangz ndeu?",
        "zh": "谁吃了一颗糖？",
        "source": "textbook"
    },
    {
        "zhuang": "Gou gwn bae.",
        "zh": "我吃掉了。",
        "source": "textbook"
    },
    {
        "zhuang": "Bouxlawz aeu bae doengj raemx haenx?",
        "zh": "谁拿了那桶水？",
        "source": "textbook"
    },
    {
        "zhuang": "De aeu bae.",
        "zh": "她拿去了。",
        "source": "textbook"
    },
    {
        "zhuang": "Cehda de ndaemndaem bae.",
        "zh": "他的眼睛黑黑的。",
        "source": "textbook"
    },
    {
        "zhuang": "Duzbya de camj dawz haenx hunghung bae.",
        "zh": "他捕到的那条鱼儿很大。",
        "source": "textbook"
    },
    {
        "zhuang": "De lumj duzgeng nei byombyangbyang bae.",
        "zh": "他像猴子似的瘦骨嶙峋。",
        "source": "textbook"
    },
    {
        "zhuang": "De rap raemx mbaeumbengmbeng bae.",
        "zh": "他挑水觉得轻飘飘的。",
        "source": "textbook"
    },
    {
        "zhuang": "Gijmak gwnz faex hoengzfwgfwg bae.",
        "zh": "树上水果红透透的。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz gaej heiq lai, gou bae yawjyawj gonq.",
        "zh": "你别太担心，我先去看看吧。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz ceiq ndei bae cawj haeux gonq.",
        "zh": "你最好先去做饭。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz cimz gonq menh gwn.",
        "zh": "你先尝尝再吃。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou swiq ndang gonq cij gwn haeuxcaeuz.",
        "zh": "我先洗完澡再吃晚饭。",
        "source": "textbook"
    },
    {
        "zhuang": "Haemh lo, gou byaij gonq lubw.",
        "zh": "晚了，我先走了啊。",
        "source": "textbook"
    },
    {
        "zhuang": "Caj de daeuj gonq, raeuz menh bae.",
        "zh": "等她来了我们再走吧。",
        "source": "textbook"
    },
    {
        "zhuang": "Caj gou yawj liux gonq, menh boiz hawj mwngz.",
        "zh": "等我看完了再还给你吧。",
        "source": "textbook"
    },
    {
        "zhuang": "Caj gou dauqma gonq, menh naeuz mwngz nyi.",
        "zh": "等我回来了再说给你听吧。",
        "source": "textbook"
    },
    {
        "zhuang": "Caj mbatlaeng ndaej doxroeb gonq, raeuz yaek gwn dwk laeuj fiz bae cij youq.",
        "zh": "待下次相见时，我们要一醉方休啊。",
        "source": "textbook"
    },
    {
        "zhuang": "Soengq de bae hwnj hag.",
        "zh": "送他去上学。",
        "source": "textbook"
    },
    {
        "zhuang": "Boenq duzgaeq deuz.",
        "zh": "把鸡赶走。",
        "source": "textbook"
    },
    {
        "zhuang": "Daiq raeuz bae guhcaemz.",
        "zh": "带我们去玩。",
        "source": "textbook"
    },
    {
        "zhuang": "Miz vunz ndwn bakdou haenx.",
        "zh": "有人站在那门口。",
        "source": "textbook"
    },
    {
        "zhuang": "Heuh de daeuj son gou sij sa w.",
        "zh": "叫他来教我写字。",
        "source": "textbook"
    },
    {
        "zhuang": "Ya wj mbouj yawj < Hoengzlouzmung > bonj saw neix?",
        "zh": "看不看《红楼梦》这本书？",
        "source": "textbook"
    },
    {
        "zhuang": "Gou rap song doengj raemx bae rued byaek ndaw suen",
        "zh": "我挑两桶水去浇园子里的菜。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz daenj buhmoq.",
        "zh": "你穿新衣服。",
        "source": "textbook"
    },
    {
        "zhuang": "Gofaex maj ndaej vaiq.",
        "zh": "树长得快。",
        "source": "textbook"
    },
    {
        "zhuang": "Aen'eij neix ga raek lo.",
        "zh": "这个椅子的腿断了。",
        "source": "textbook"
    },
    {
        "zhuang": "Haemhneix fwn doek.",
        "zh": "今晚有雨。",
        "source": "textbook"
    },
    {
        "zhuang": "Ngoenz ngoenz cungj doek fwn'oemq.",
        "zh": "每天都阴雨绵绵。",
        "source": "textbook"
    },
    {
        "zhuang": "Ndaw gyausiz miz hagseng hwnjdangz.",
        "zh": "教室里有学生上课。",
        "source": "textbook"
    },
    {
        "zhuang": "Song boux lwg cungj gauj ndaej hwnj lo.",
        "zh": "两个儿子都考上了。",
        "source": "textbook"
    },
    {
        "zhuang": "Raemx ndaw gu gunj lo.",
        "zh": "锅里的水开了。",
        "source": "textbook"
    },
    {
        "zhuang": "Duzroeg gwnzfaex mbin lo.",
        "zh": "树上的鸟飞了。",
        "source": "textbook"
    },
    {
        "zhuang": "Gangj gaih gvaq guh.",
        "zh": "说比做容易。",
        "source": "textbook"
    },
    {
        "zhuang": "Gwn haeux gaej genj.",
        "zh": "吃饭别挑食。",
        "source": "textbook"
    },
    {
        "zhuang": "Ndwn dwk mbouj doengh hoj dangqmaz.",
        "zh": "站着不动很难。",
        "source": "textbook"
    },
    {
        "zhuang": "Baez naengh couh seiq diemjcung.",
        "zh": "一坐就是四个小时。",
        "source": "textbook"
    },
    {
        "zhuang": "Na ndei, mbang lai daenj mbouj raeuj.",
        "zh": "厚了好，太薄穿了不暖和。",
        "source": "textbook"
    },
    {
        "zhuang": "Vaiq hix mbouj dwg, nguh hix mbouj dwg.",
        "zh": "快也不是，慢也不是。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz bae caemh ndaej.",
        "zh": "你去也成。",
        "source": "textbook"
    },
    {
        "zhuang": "Ngaenz lai mbouj itdingh baenz.",
        "zh": "钱多未必好。",
        "source": "textbook"
    },
    {
        "zhuang": "Saw yawj lai gyaeuj dot.",
        "zh": "书看多了头疼。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou hawj cij ndaej doengh.",
        "zh": "我允许才能动。",
        "source": "textbook"
    },
    {
        "zhuang": "Boux neix bouxcuengh.",
        "zh": "这个人是壮族。",
        "source": "textbook"
    },
    {
        "zhuang": "De ginsiyanj.",
        "zh": "他是近视眼。",
        "source": "textbook"
    },
    {
        "zhuang": "Ngoenzcog sam nyied sam.",
        "zh": "明天是三月三。",
        "source": "textbook"
    },
    {
        "zhuang": "Boux song aen.",
        "zh": "每人两个。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz baenzlawzyangh?",
        "zh": "你怎么样？",
        "source": "textbook"
    },
    {
        "zhuang": "Gou vunz Gvangjsih.",
        "zh": "我是广西人。",
        "source": "textbook"
    },
    {
        "zhuang": "Dahnuengx gou goet sang.",
        "zh": "我妹妹是个高个儿的。",
        "source": "textbook"
    },
    {
        "zhuang": "De cibbet, gou ngeihcib.",
        "zh": "他十八，我二十。",
        "source": "textbook"
    },
    {
        "zhuang": "Bonj saw neix bet maenz ngaenz.",
        "zh": "这本书八块钱。",
        "source": "textbook"
    },
    {
        "zhuang": "Duzvaiz gwn nywj.",
        "zh": "牛吃草。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou roxnaj de.",
        "zh": "我认识他。",
        "source": "textbook"
    },
    {
        "zhuang": "De rox gangj VahCuengh.",
        "zh": "他会说壮话。",
        "source": "textbook"
    },
    {
        "zhuang": "Daeg neix lumj daxboh de.",
        "zh": "这男孩像他爸爸。",
        "source": "textbook"
    },
    {
        "zhuang": "De daengz Bwzgingh gvaq.",
        "zh": "他到过北京。",
        "source": "textbook"
    },
    {
        "zhuang": "De dwg vunz baihbaek.",
        "zh": "他是北方人。",
        "source": "textbook"
    },
    {
        "zhuang": "Ngoenzlwenz nit, ngoenzneix haemq raeuj.",
        "zh": "昨天冷，今天较暖和。",
        "source": "textbook"
    },
    {
        "zhuang": "Aen gva neix diemz raixcaix.",
        "zh": "这个瓜很甜。",
        "source": "textbook"
    },
    {
        "zhuang": "Ndaw gyausiz seuqsatsat.",
        "zh": "教室里干干净净的。",
        "source": "textbook"
    },
    {
        "zhuang": "Ndaw ranz nyaed lai.",
        "zh": "屋里太挤。",
        "source": "textbook"
    },
    {
        "zhuang": "Gwnz congz nyungqnyatnyat.",
        "zh": "床上乱七八糟的。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou bae laj mbanj.",
        "zh": "我去乡下。",
        "source": "textbook"
    },
    {
        "zhuang": "Raeuz haeuj gyausiz.",
        "zh": "咱们进教室。",
        "source": "textbook"
    },
    {
        "zhuang": "Dah de buet ok doumonz.",
        "zh": "那个女孩跑出大门。",
        "source": "textbook"
    },
    {
        "zhuang": "Daeg de benz hwnj gwnzlouz.",
        "zh": "那个男孩爬上楼顶。",
        "source": "textbook"
    },
    {
        "zhuang": "De ngoenzcog daeuj laeng gou.",
        "zh": "他明天来我家。",
        "source": "textbook"
    },
    {
        "zhuang": "Gwnz ciengz did go nywj ndeu.",
        "zh": "墙上长一棵草。",
        "source": "textbook"
    },
    {
        "zhuang": "Najmbanj vat diuz mieng ndeu.",
        "zh": "村前挖一条水沟。",
        "source": "textbook"
    },
    {
        "zhuang": "Laj daiz miz duz ma ndeu.",
        "zh": "桌子下有一只狗。",
        "source": "textbook"
    },
    {
        "zhuang": "Ndaw rug diemj aen daeng ndeu.",
        "zh": "卧室里点了一盏灯。",
        "source": "textbook"
    },
    {
        "zhuang": "Gwnz roen law bae aen habbau ndeu.",
        "zh": "在路上丢失了个钱包。",
        "source": "textbook"
    },
    {
        "zhuang": "De gyaeu gijmaz.",
        "zh": "她漂亮什么。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz riu gijmaz.",
        "zh": "你笑什么。",
        "source": "textbook"
    },
    {
        "zhuang": "Sou hemq gijmaz.",
        "zh": "你们喊什么。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz byaij duh mwngz.",
        "zh": "你走你的。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou bae cam he baez ndeu.",
        "zh": "我去问它一次。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz ciengq he duenh ndeu.",
        "zh": "你唱它一段。",
        "source": "textbook"
    },
    {
        "zhuang": "Gonj bit neix gonj duh gou.",
        "zh": "这支笔是我的。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou siengj gwn vanj raemx ndeu.",
        "zh": "我想喝一碗水。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou roxnyinh miz di nit.",
        "zh": "我觉得有点儿冷。",
        "source": "textbook"
    },
    {
        "zhuang": "De ngvanh baenzlawz guh ndei.",
        "zh": "他想如何做好。",
        "source": "textbook"
    },
    {
        "zhuang": "De ngeix guh gijmaz saeh ngoenzlwenz.",
        "zh": "他回忆昨天做了什么事。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou loqraen miz vunz heuh.",
        "zh": "我梦见有人叫。",
        "source": "textbook"
    },
    {
        "zhuang": "De daenj diuz buh moqsupsup ndeu.",
        "zh": "她穿件崭新的衣服。",
        "source": "textbook"
    },
    {
        "zhuang": "Dangqnaj miz go faex youh hung youh sang ndeu.",
        "zh": "前面有棵高大的树。",
        "source": "textbook"
    },
    {
        "zhuang": "Aen mak henjrwgrwg neix.",
        "zh": "这个熟透了的果子。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou ndaenj haeuj aenranz laepsaengsaeng bae.",
        "zh": "我走进黑漆漆的那个房子。",
        "source": "textbook"
    },
    {
        "zhuang": "Ndaek vengq fwj mdaemraeuraeu ndeu daj baihdoeng vaij gvaq daeuj.",
        "zh": "一大片黑黑的乌云从东边压过来。",
        "source": "textbook"
    },
    {
        "zhuang": "Laeng de miz hek daeuj.",
        "zh": "他家来了客人。",
        "source": "textbook"
    },
    {
        "zhuang": "Haeux bi'moq lw lai.",
        "zh": "去年的稻谷剩的多。",
        "source": "textbook"
    },
    {
        "zhuang": "Duzroeg gwnz faex heuhgyigyi.",
        "zh": "树上的鸟儿喳喳叫。",
        "source": "textbook"
    },
    {
        "zhuang": "Boux lwgnyez neix caeuq gou bae.",
        "zh": "这个孩子和我去。",
        "source": "textbook"
    },
    {
        "zhuang": "Aen ranz cien neix aen gou.",
        "zh": "这个砖房是我的。",
        "source": "textbook"
    },
    {
        "zhuang": "Lwgsawz dumq ndei gwn raixcaix.",
        "zh": "煮的白薯很好吃",
        "source": "textbook"
    },
    {
        "zhuang": "Raeuz roengzrengz doeg saw.",
        "zh": "我们努力地读书。",
        "source": "textbook"
    },
    {
        "zhuang": "De ak gwn ak guh.",
        "zh": "他能吃又能干。",
        "source": "textbook"
    },
    {
        "zhuang": "De menhmenh benz hwnj louz.",
        "zh": "他慢慢地爬上楼。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz gik byaij roen, couh gaej bae lo.",
        "zh": "你懒得走路，就别去了。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz dinghdingh cuengq doxgaiq roengzdaeuj.",
        "zh": "你把东西轻轻地放下来。",
        "source": "textbook"
    },
    {
        "zhuang": "De ngamj bae hwnjban.",
        "zh": "他刚去上班。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou ngoenzlwenz daeuj laeng de.",
        "zh": "我昨天来他家。",
        "source": "textbook"
    },
    {
        "zhuang": "Duznou caegcaeg riqgvaq henzciengz.",
        "zh": "老鼠悄悄地从墙根跑过。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou yaek hag mwngz ciengq go.",
        "zh": "我要学你唱歌。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz youq ranz yawj saw lwi?",
        "zh": "你在家看书吗？",
        "source": "textbook"
    },
    {
        "zhuang": "Raeuz cug go cug go raemj faex.",
        "zh": "我们一棵一棵地砍着树。",
        "source": "textbook"
    },
    {
        "zhuang": "De cij gangj coenz vah dog.",
        "zh": "他只说了一句话。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou daj ndaw dou yawj okbae.",
        "zh": "我从门里往外看。",
        "source": "textbook"
    },
    {
        "zhuang": "Gangj byoedbyoed byadbyad.",
        "zh": "叽里呱啦地说着。",
        "source": "textbook"
    },
    {
        "zhuang": "Byaij ngungxngungx ngangxngangx.",
        "zh": "跌跌撞撞地走着。",
        "source": "textbook"
    },
    {
        "zhuang": "Gvih gyoedgyoed gyaxgyax.",
        "zh": "小孩跪着玩耍貌。",
        "source": "textbook"
    },
    {
        "zhuang": "Gwn ndaek gaemz ndaek gaemz.",
        "zh": "大口大口地吃着。",
        "source": "textbook"
    },
    {
        "zhuang": "De ninz yawj saw.",
        "zh": "他躺着看书。",
        "source": "textbook"
    },
    {
        "zhuang": "Lwgbiek cawj hix baenz gwn.",
        "zh": "芋头煮着也好吃。",
        "source": "textbook"
    },
    {
        "zhuang": "Naz hawq lo, raemx dwk lai di.",
        "zh": "水田干了，要多灌溉一些水。",
        "source": "textbook"
    },
    {
        "zhuang": "Ngah noh lo, noh heh lai di.",
        "zh": "谗肉了，肉要多切点儿。",
        "source": "textbook"
    },
    {
        "zhuang": "De ndwen bae haw cawx byaek song baez.",
        "zh": "他每月到集市上买两回菜。",
        "source": "textbook"
    },
    {
        "zhuang": "De baez raemj go faex ndeu.",
        "zh": "他每次砍一棵树。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz ndauj haeux ywnz bae.",
        "zh": "你把米拌均匀了。",
        "source": "textbook"
    },
    {
        "zhuang": "De dub aenvanj ywngz lo.",
        "zh": "他把碗打碎了。",
        "source": "textbook"
    },
    {
        "zhuang": "Yumz gaiqbaengz hoengz lo.",
        "zh": "把布染红了。",
        "source": "textbook"
    },
    {
        "zhuang": "Lot faexndoek soemsoem bae.",
        "zh": "把竹子削得尖尖的。",
        "source": "textbook"
    },
    {
        "zhuang": "De sij cihsa wloek lo.",
        "zh": "他把字写错了。",
        "source": "textbook"
    },
    {
        "zhuang": "Duz ma neix yak ya wj yaek dai.",
        "zh": "这只狗难看死了。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou nit dwk yaek dai.",
        "zh": "我冻得要死了。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz gangj yaek ci ngcuj.",
        "zh": "你要讲清楚。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou hozhawq dwk yaek dai ngoz lo.",
        "zh": "我渴得快要枯死了",
        "source": "textbook"
    },
    {
        "zhuang": "Duz ma de deng vunz dub dwk yaek gyad lo.",
        "zh": "那只狗被人打得快要残废了。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz aeu aendaengq daeuj.",
        "zh": "你把凳子拿来。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou soengq gonj bit bae.",
        "zh": "我送一支笔去。",
        "source": "textbook"
    },
    {
        "zhuang": "De ngoenzl wenz gei q haujlai ngaenz ma.",
        "zh": "他昨天寄了很多钱回来。",
        "source": "textbook"
    },
    {
        "zhuang": "De daxbaenh bae aeu noegcae ndaw reih dauq.",
        "zh": "他刚才去把地里的犁头拿回来。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou yawj hwzbanj ndaej raen.",
        "zh": "我能看得见黑板。",
        "source": "textbook"
    },
    {
        "zhuang": "Bien faenzcieng neix sij ndaej liux.",
        "zh": "这篇文章能写完。",
        "source": "textbook"
    },
    {
        "zhuang": "De saet ndaej gvaq gumz.",
        "zh": "他能跳过这坑儿。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou di ngq ndaej rox.",
        "zh": "我能听懂。",
        "source": "textbook"
    },
    {
        "zhuang": "Duzbit saez ndaej dawz bya.",
        "zh": "鸭子能抓到鱼。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou nit dwk saenzdwddwd.",
        "zh": "我冷得发抖。",
        "source": "textbook"
    },
    {
        "zhuang": "De ndwn dwk hwet naet.",
        "zh": "我站得腰累了。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou hwngq dwk ok hanh.",
        "zh": "我热得出了汗。",
        "source": "textbook"
    },
    {
        "zhuang": "De manh dwk raemxda ri h.",
        "zh": "她被辣得流了眼泪。",
        "source": "textbook"
    },
    {
        "zhuang": "De gwn dwk bak youzyubyub.",
        "zh": "他吃得满嘴流油。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou dungx iek dwk dungx doxnemlo.",
        "zh": "我饿得肚子都贴到一起了。、",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz deq gou yaep ndeu.",
        "zh": "你等我一会儿。",
        "source": "textbook"
    },
    {
        "zhuang": "De youq Bwzgi ngh sa m bi.",
        "zh": "他在北京住了三年。",
        "source": "textbook"
    },
    {
        "zhuang": "Aenbiuj mwngz byaij nguh song faenhcung.",
        "zh": "你的表走慢了两分钟。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou ngoenzl wenz ya wj denyi ngj baenzngoenz.",
        "zh": "我昨天看了一天的电影。",
        "source": "textbook"
    },
    {
        "zhuang": "De guhcaeg deng gyaeng baengz cib ndawen.",
        "zh": "他因盗窃被关了整整十个月。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou doeg bonj saw neix song baez.",
        "zh": "我读了两次这本书。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou yawj boux de mbat ndeu.",
        "zh": "我看了那个人一眼。",
        "source": "textbook"
    },
    {
        "zhuang": "Raeuz raen naj gvaq geij mbat.",
        "zh": "我们见过几次面。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou nga mq cawx song gaen noh.",
        "zh": "我只买两斤肉。",
        "source": "textbook"
    },
    {
        "zhuang": "Diuzvaq neix raez conq ndeu.",
        "zh": "这条裤子长了一寸。",
        "source": "textbook"
    },
    {
        "zhuang": "De deng daxboh dub angjfwngz song baez.",
        "zh": "他被父亲打了两下手心。",
        "source": "textbook"
    },
    {
        "zhuang": "Aen louz neix sang gvaq aenhaenx song boix.",
        "zh": "这栋楼比那栋楼高两倍。",
        "source": "textbook"
    },
    {
        "zhuang": "Ca wx gij byaek neix cienh haujlai ngaenz.",
        "zh": "买这些菜便宜了很多钱。",
        "source": "textbook"
    },
    {
        "zhuang": "Duzroeg mbi n dwk byux.",
        "zh": "鸟儿“扑”地一声飞了。",
        "source": "textbook"
    },
    {
        "zhuang": "De hup aendou dwk gumx.",
        "zh": "他“乓”地一声关上门。",
        "source": "textbook"
    },
    {
        "zhuang": "Gofaex raek dwk hat.",
        "zh": "树“哒”地一声断了。",
        "source": "textbook"
    },
    {
        "zhuang": "De ae dwk gvemz.",
        "zh": "他咳嗽了一声。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou haengj nin ai.",
        "zh": "我喜欢仰着睡。",
        "source": "textbook"
    },
    {
        "zhuang": "Cungj byaek neix ndaej gwn ndip.",
        "zh": "这种菜能生吃。",
        "source": "textbook"
    },
    {
        "zhuang": "De naengh vang lai.",
        "zh": "他横着坐的多。",
        "source": "textbook"
    },
    {
        "zhuang": "De daxbaenh laemx hoemj.",
        "zh": "他刚才跌倒了。",
        "source": "textbook"
    },
    {
        "zhuang": "De ga mj byaij roen laep ne, gou couh byaij dingqgit.",
        "zh": "你若敢走夜路，我就倒立着走。",
        "source": "textbook"
    },
    {
        "zhuang": "Duz gaeql wg neix dai nyungz.",
        "zh": "这只小鸡死于被蚊子叮咬。",
        "source": "textbook"
    },
    {
        "zhuang": "Go faexl wg neix dai ndit.",
        "zh": "这棵小树是死于阳光太强。",
        "source": "textbook"
    },
    {
        "zhuang": "Aen ci de loemq boengz.",
        "zh": "那辆车陷于泥潭。",
        "source": "textbook"
    },
    {
        "zhuang": "Duz ma neix ndoq gyak.",
        "zh": "这只狗因癣而掉光了毛。",
        "source": "textbook"
    },
    {
        "zhuang": "Gyaeng hawj de dai nit bae.",
        "zh": "关着它直到被冻死。",
        "source": "textbook"
    },
    {
        "zhuang": "Raeuz dik haeuj aen giuz ndeu.",
        "zh": "我们踢进了一个球。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz rap song doengj raemx.",
        "zh": "你挑两桶水。",
        "source": "textbook"
    },
    {
        "zhuang": "De ja wj bonj saw ndeu.",
        "zh": "他看一本书。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou cawx song gaen noh.",
        "zh": "我买两斤肉。",
        "source": "textbook"
    },
    {
        "zhuang": "Mou iq maj hung.",
        "zh": "小猪长得大。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou di ngq rox.",
        "zh": "我能听得懂。",
        "source": "textbook"
    },
    {
        "zhuang": "De doeksaet yat.",
        "zh": "她吓了一跳。",
        "source": "textbook"
    },
    {
        "zhuang": "Duzgaeq cak byux.",
        "zh": "鸡“扑”地挣扎了一下。",
        "source": "textbook"
    },
    {
        "zhuang": "Mbouj yungh ca m, gou rox vi hmaz de ndoj gou.",
        "zh": "不用问，我知道为什么她躲着我。",
        "source": "textbook"
    },
    {
        "zhuang": "Cungj ma gangj, mbouj miz raemx raeuz couh dai.",
        "zh": "总的来说，没有水，我们就会死去。",
        "source": "textbook"
    },
    {
        "zhuang": "Ci bbi gonq, caemhdwg bi 1993, de bae doeg dayoz.",
        "zh": "十年前，即1993年，他去上大学。",
        "source": "textbook"
    },
    {
        "zhuang": "Duz mou neix, gou yawj aiq miz song bak gaen.",
        "zh": "这头猪，我看可能有二百斤。",
        "source": "textbook"
    },
    {
        "zhuang": "De mbouj hwnjban, dingqnaeuz de laeuj fiz lo.",
        "zh": "他没上班，听说他醉酒了。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz yawj, mwngz ceng di caeuh laemx lo.",
        "zh": "你看，你差点儿就摔倒了。",
        "source": "textbook"
    },
    {
        "zhuang": "De l umj naeuz mbouj youq ranz.",
        "zh": "他好像不在家。",
        "source": "textbook"
    },
    {
        "zhuang": "Duz mou neix noixgangj cungj miz song bak gaen.",
        "zh": "这头猪至少有二百斤重。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz vaiq di gwn, Genmingz.",
        "zh": "你快点吃，建明。",
        "source": "textbook"
    },
    {
        "zhuang": "Vei, mwngz heuh coh maz?",
        "zh": "喂，你叫什么名字？",
        "source": "textbook"
    },
    {
        "zhuang": "Boh, mwngz seizlawz daeuj laeng gou youq?",
        "zh": "爸，你什么时候来我家住？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz mbouj ndaej yienghneix guh, Lauj Vangz.",
