        "source": "textbook"
    },
    {
        "zhuang": "Donghdongh danghdangh, hwnj dangz lo. \"",
        "zh": "叮叮当当”，上课了。",
        "source": "textbook"
    },
    {
        "zhuang": "Yox, ndaek vunz mwngz naengh l umj you nei ha wj gou dungxcieg li ux.",
        "zh": "哟，你这个人坐着像石像一样一声不吭，吓了我一跳。",
        "source": "textbook"
    },
    {
        "zhuang": "De dwg dahcej mwngz lwi?",
        "zh": "她是你姐姐吗？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz roxnaj dahnuengx de ha?",
        "zh": "你认识他妹妹吗？",
        "source": "textbook"
    },
    {
        "zhuang": "Hawj gou nw?",
        "zh": "是给我的吗？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz caeuq raeuz bae la?",
        "zh": "你跟我们去吗？",
        "source": "textbook"
    },
    {
        "zhuang": "De vunz laeng raeuz?",
        "zh": "他是我们那儿的人？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz bae guh seng'eiq?",
        "zh": "你去做生意？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz mbouj bae?",
        "zh": "你不去？",
        "source": "textbook"
    },
    {
        "zhuang": "Daxgoeng de lij da raeh?",
        "zh": "他爷爷的眼睛还好？",
        "source": "textbook"
    },
    {
        "zhuang": "Byawz ngoenzlwenz daeuj laeng gou yawj saw lo?",
        "zh": "谁昨天到我家看书了？",
        "source": "textbook"
    },
    {
        "zhuang": "De seizlawz daeuj laeng gou yawj saw lo?",
        "zh": "他什么时候到家我看书了？",
        "source": "textbook"
    },
    {
        "zhuang": "De ngoenzlwenz daeuj gizlawz yawj saw lo?",
        "zh": "他昨天到哪儿看书了？",
        "source": "textbook"
    },
    {
        "zhuang": "De ngoenzlwenz daeuj laeng gou guh maz lo?",
        "zh": "他昨天到我家干什么了？",
        "source": "textbook"
    },
    {
        "zhuang": "De ngoenzlwenz daeuj laeng gou yawj gijmaz lo.",
        "zh": "他昨天到我家看什么了？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz bae roxnaeuz mbouj bae?",
        "zh": "你去还是不去？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz gwn roxnaeuz mbouj gwn?",
        "zh": "你吃还是不吃？",
        "source": "textbook"
    },
    {
        "zhuang": "Gou deuz roxnaeuz mbouj deuz?",
        "zh": "我走还是不走？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz gvai roxnaeuz ngawz?",
        "zh": "你聪明还是傻？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz naengh roxnaeuz ndwn?",
        "zh": "你坐着还是站着？",
        "source": "textbook"
    },
    {
        "zhuang": "Gou doxbae roxnaeuz doxdauq?",
        "zh": "我往前还是往后？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz yawj saw roxnaeuz yawj bauceij?",
        "zh": "你看书还是看报？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz gwn haeux roxnaeuz gwn mienh?",
        "zh": "你吃米饭还是吃面条？",
        "source": "textbook"
    },
    {
        "zhuang": "Gou rap haeuxraeh roxnaeuz rap haeuxsan?",
        "zh": "我挑稻谷还是大米？",
        "source": "textbook"
    },
    {
        "zhuang": "Gou raemj roxnaeuz mwngz raemj?",
        "zh": "我砍还是你砍？",
        "source": "textbook"
    },
    {
        "zhuang": "Gou bae roxnaeuz mwngz bae?",
        "zh": "我去还是你去？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz hai ci roxnaeuz de hai ci?",
        "zh": "你开车还是他开车？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz dwg mbouj dwg vunz Haijnamz?",
        "zh": "你是不是海南人？",
        "source": "textbook"
    },
    {
        "zhuang": "De haengj mbouj haengj caeuq mwngz youq?",
        "zh": "她喜欢不喜欢和你在一起？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz dajcaemx mbouj dajcaemx?",
        "zh": "你游泳不游泳？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz naeuz de gik mbouj gik?",
        "zh": "你说他懒不懒？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz gangj riu ba?",
        "zh": "你开玩笑吧？",
        "source": "textbook"
    },
    {
        "zhuang": "De ngoenzneix youq ranz ba?",
        "zh": "他今天在家吧？",
        "source": "textbook"
    },
    {
        "zhuang": "Lwg neix lwg de ba?",
        "zh": "这孩子是她的吧？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz daeuj laeng gou gvaq ba?",
        "zh": "你来过我家吧？",
        "source": "textbook"
    },
    {
        "zhuang": "De dwg daxboh gou.",
        "zh": "他是我父亲。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz dwg vunz gizlawz lo?",
        "zh": "你是哪里人呀？",
        "source": "textbook"
    },
    {
        "zhuang": "Gou dwg daj Gvangjsih daeuj.",
        "zh": "我是从广西来的。",
        "source": "textbook"
    },
    {
        "zhuang": "Boux ndwn bakdou dwg daxmeh gou.",
        "zh": "站在门口的是我妈妈。",
        "source": "textbook"
    },
    {
        "zhuang": "De lwg daxlungz gou.",
        "zh": "他是我伯父的孩子。",
        "source": "textbook"
    },
    {
        "zhuang": "Daxmeh gou vunz laj mbanj.",
        "zh": "我妈是乡下人。",
        "source": "textbook"
    },
    {
        "zhuang": "Boux byaij gvaq daeuj dahcej gou.",
        "zh": "走过来的是我姐姐。",
        "source": "textbook"
    },
    {
        "zhuang": "Duz ndaem duz de.",
        "zh": "黑的那头是他的。",
        "source": "textbook"
    },
    {
        "zhuang": "Gonjbit gwnz daiz gonj duh gou.",
        "zh": "桌子上的笔是我的。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz diuz rap cuengq roengz daeuj.",
        "zh": "把担子放下来。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz bonjsaw neix sik bae.",
        "zh": "把这本书撕了。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz aendou gven ndei.",
        "zh": "把门关好。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz aenmauh duet bae.",
        "zh": "把帽子脱掉。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz aenriep saeg seuq bae.",
        "zh": "把蚊帐洗干净了。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz bak daej cug hwnjdaeuj.",
        "zh": "把袋子口扎起来。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz aen vanj de swiq bae.",
        "zh": "把那个碗洗了。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz aen vanj de bae swiq.",
        "zh": "拿那个碗去洗了。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz bat raemx de bok bae.",
        "zh": "把那盆水倒了。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz bat raemx de daeuj bok.",
        "zh": "把那盆水倒了。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz diuz buh de daenj lo.",
        "zh": "把那件衣服穿了。",
        "source": "textbook"
    },
    {
        "zhuang": "Dawz diuz buh de daeuj daenj lo.",
        "zh": "拿那件衣服来穿了。",
        "source": "textbook"
    },
    {
        "zhuang": "Ok ndit lo.",
        "zh": "出太阳了",
        "source": "textbook"
    },
    {
        "zhuang": "Hwnj dangz le.",
        "zh": "上课了",
        "source": "textbook"
    },
    {
        "zhuang": "Ok rumz lo.",
        "zh": "刮风了。",
        "source": "textbook"
    },
    {
        "zhuang": "Doek fwn lo.",
        "zh": "下雨了",
        "source": "textbook"
    },
    {
        "zhuang": "Ndwn dwk!",
        "zh": "站着",
        "source": "textbook"
    },
    {
        "zhuang": "Re!",
        "zh": "注意！",
        "source": "textbook"
    },
    {
        "zhuang": "Dai lo, yuep bae!",
        "zh": "天哪，真是惊心动魄！",
        "source": "textbook"
    },
    {
        "zhuang": "Heuh de daeuj laeng gou guhcaemz.",
        "zh": "请他来我家玩。",
        "source": "textbook"
    },
    {
        "zhuang": "Aeu aendaeh daeuj hawj gou.",
        "zh": "把袋子拿来给我。",
        "source": "textbook"
    },
    {
        "zhuang": "Raemj faexdan ma san aen'gyoi.",
        "zh": "砍竹子来编个泥箕。",
        "source": "textbook"
    },
    {
        "zhuang": "Itdingh guh hong liux bae!",
        "zh": "一定要完成任务！",
        "source": "textbook"
    },
    {
        "zhuang": "Yaek roengzrengz doegsaw!",
        "zh": "要努力学习！",
        "source": "textbook"
    },
    {
        "zhuang": "Ak raixcaix!",
        "zh": "很有水平！",
        "source": "textbook"
    },
    {
        "zhuang": "Gvai lai lo.",
        "zh": "太聪明了。",
        "source": "textbook"
    },
    {
        "zhuang": "Ndei dangqmaz!",
        "zh": "真好！",
        "source": "textbook"
    },
    {
        "zhuang": "Gaej louzsou!",
        "zh": "别淘气！",
        "source": "textbook"
    },
    {
        "zhuang": "Gyaeu!",
        "zh": "漂亮！",
        "source": "textbook"
    },
    {
        "zhuang": "Yinx raixcaix bae!",
        "zh": "太有意思了！",
        "source": "textbook"
    },
    {
        "zhuang": "Bengz lai!",
        "zh": "太贵了！",
        "source": "textbook"
    },
    {
        "zhuang": "Ndaengq lai!",
        "zh": "太咸了！",
        "source": "textbook"
    },
    {
        "zhuang": "Gou gwn haeux sat, couh bae guhcaemz.",
        "zh": "我吃完饭，就出去玩。",
        "source": "textbook"
    },
    {
        "zhuang": "Mbouj guh hong liux, couh mbouj ma ranz.",
        "zh": "不把活儿做完，决不回家。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz yied buet, duzma yied raeuq; mwngz dingh youq, duzma daujfanj soh.",
        "zh": "你越跑，狗叫得越凶;你安静，狗反而老实。",
        "source": "textbook"
    },
    {
        "zhuang": "Gwn haeux lau saek'iek, byaij roen lau daemj ndoet.",
        "zh": "吃饭怕噎着，走路怕磕碰。",
        "source": "textbook"
    },
    {
        "zhuang": "Danghnaeuz mwngz mbouj guh ndei, gou seizneix couh bae naeuz daxboh nyi.",
        "zh": "如果你不好好做，我现在就去告诉爸爸。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz siengj hawj gaeqmeh ok gyaeq lai, youh mbouj hawj de gwn haeux.",
        "zh": "你要让母鸡多下蛋，又不给它吃的。",
        "source": "textbook"
    },
    {
        "zhuang": "De daej, mwngz caemh daej.",
        "zh": "她哭，你也哭。",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz doeg, roxnaeuz gou doeg?",
        "zh": "你读，还是我读？",
        "source": "textbook"
    },
    {
        "zhuang": "Danghnaeuz mwngz bae, gou caemh bae.",
        "zh": "如果你去，我也去。",
        "source": "textbook"
    },
    {
        "zhuang": "De gvai raixcaix, hoeng miz di gik.",
        "zh": "他很聪明，但有些懒。",
        "source": "textbook"
    },
    {
        "zhuang": "Cijmiz mwngz, cij guh ndaej ndei baenzneix.",
        "zh": "只有你，才做得这么好",
        "source": "textbook"
    },
    {
        "zhuang": "Mboujlwnh mwngz roxnaeuz de, cungj mbouj ndaej noix.",
        "zh": "无论你还是他，都不能少。",
        "source": "textbook"
    },
    {
        "zhuang": "Couhdwg mbwn laep, gou hix mbouj lau.",
        "zh": "就是天黑，我也不怕。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou bae heuh de, mbouj miz vunz han.",
        "zh": "我去叫她，没人应答。",
        "source": "textbook"
    },
    {
        "zhuang": "Mbwn laep lo, gou mbouj ma ranz lo.",
        "zh": "天黑，我不回家了。",
        "source": "textbook"
    },
    {
        "zhuang": "Hwet naet lo, de hix mbouj yietbaeg.",
        "zh": "腰酸背疼的了，他也不休息。",
        "source": "textbook"
    },
    {
        "zhuang": "De doq mbuk haeuj rongzroeg bae, duz de byux mbin ok daeuj lo.",
        "zh": "他一摸进鸟窝，一只鸟“扑”地突然飞了出来。",
        "source": "textbook"
    },
    {
        "zhuang": "Rumz dingz lo, fwn caemh ding lo.",
        "zh": "风停了，雨也停了。",
        "source": "textbook"
    },
    {
        "zhuang": "De youh guh boh, youh guh meh.",
        "zh": "他又当爹，又当娘。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou rox gangj vahCuengh, hix rox gangj vahDe ih.",
        "zh": "我会说壮语，也会说泰语。",
        "source": "textbook"
    },
    {
        "zhuang": "Lwgnyez de yaep daej, yaep riu.",
        "zh": "她的孩子一会儿哭，一会儿笑。",
        "source": "textbook"
    },
    {
        "zhuang": "Mboujdwg gou hingz, couhdwg gou saw.",
        "zh": "不是我赢，就是我输。",
        "source": "textbook"
    },
    {
        "zhuang": "De sam ban, gou haj ban.",
        "zh": "她是三班，我是五班。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou vunz Gvangjsih, de vunz Huznamz.",
        "zh": "我广西人，她湖南人。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou doxngoenz hwnjdangz, doxhaemh guh hong.",
        "zh": "我白天学习，晚上打工。",
        "source": "textbook"
    },
    {
        "zhuang": "Vunz gik mbouj miz gwn, vunz gaenz cix haeux rim ranz.",
        "zh": "懒惰的人没有吃的，勤劳的人却粮满仓。",
        "source": "textbook"
    },
    {
        "zhuang": "Raeuz bae, roxnaeuz gyoengqde daeuj?",
        "zh": "我们去，还是他们来？",
        "source": "textbook"
    },
    {
        "zhuang": "Mwngz youq ndawranz roxnaeuz youq baihrog?",
        "zh": "你在家里还是在外边？",
        "source": "textbook"
    },
    {
        "zhuang": "Dwg gwn mandouz, roxnaeuz gwn haeuxndangj?",
        "zh": "是吃馒头，还是吃干米饭？",
        "source": "textbook"
    },
    {
        "zhuang": "Dwg ndwn aeu roxnaeuz naengh aeu?",
        "zh": "是站着还是坐着？",
        "source": "textbook"
    },
    {
        "zhuang": "Ngoenzneix mbouj mwngz uet hwzbanj, couh de uet hwzbanj.",
        "zh": "今天不是你擦黑板，就是他擦黑板。",
        "source": "textbook"
    },
    {
        "zhuang": "Mbouj mwngz hingz lo, couh de hingz lo.",
        "zh": "不是你赢了，就是他赢了。",
        "source": "textbook"
    },
    {
        "zhuang": "Mbouj gou heuh mwngz, cix mwngz heuh gou.",
        "zh": "不是我叫你，就是你叫我。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou ningznyienh dungx iek, hix mbouj gwn gij mwngz.",
        "zh": "我宁可饿着肚子，也不能吃你的。",
        "source": "textbook"
    },
    {
        "zhuang": "Ningznyienh gungz di, hix mbouj bae guhcaeg.",
        "zh": "宁愿穷点儿，也不去做贼。",
        "source": "textbook"
    },
    {
        "zhuang": "Ndaem faexcoengz, mbouj lumj ndaem faexdan.",
        "zh": "与其种松树，不如种竹子。",
        "source": "textbook"
    },
    {
        "zhuang": "Hawj de bae guh, mbouj lumj hawj gou bae guh.",
        "zh": "与其让他去办，不如让我去办。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou yawj sat le, couh boiz hawj mwngz nw.",
        "zh": "我看完了，就还给你啊。",
        "source": "textbook"
    },
    {
        "zhuang": "Raeuz guh hong haujlai nanz lo, aendaengngoenz cij daj baihdoeng ok daeuj.",
        "zh": "我们劳动都好一会儿了，太阳才从东边出来。",
        "source": "textbook"
    },
    {
        "zhuang": "Sou bae laeng degonq, caiq daeuj laeng goudoeklaeng.",
        "zh": "你们先去他家，再来我家。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou ngamq haeuj ranz, couh ciep ndaej denva mwngz.",
        "zh": "我刚回到家，就接到你的电话。",
        "source": "textbook"
    },
    {
        "zhuang": "Lwg de yied daej, de yied dub.",
        "zh": "他的孩子越哭，他越打。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou ma ranz aeu bonj saw ndeu.",
        "zh": "我回家拿本书。",
        "source": "textbook"
    },
    {
        "zhuang": "Gou heuh de daeuj guhcaemz.",
